const LON0 = -17.0;
const LAT1 = 47.5;
const SCALE = 32.0;
const COS = Math.cos((32 * Math.PI) / 180);

/** Longitude/latitude to base-map units. */
export const projectMediterranean = (lon: number, lat: number): [number, number] => [
  (lon - LON0) * COS * SCALE,
  (LAT1 - lat) * SCALE,
];

/** Base-map units back to longitude/latitude (for taps on the map). */
export const unprojectMediterranean = (x: number, y: number): [number, number] => [
  LON0 + x / (COS * SCALE),
  LAT1 - y / SCALE,
];

/** Base-map units for one kilometre (north-south), for the scale bar. */
export const MEDITERRANEAN_UNITS_PER_KM = SCALE / 111.2;
